def summarize(values: list[int]) -> str:
    label = Path(__file__).with_name("label.txt").read_text(encoding="utf-8").strip()
    return f"{label}: {sum(values)}"


def main() -> None:
    print(summarize([2, 5]))


if __name__ == "__main__":
    main()

